    ['Matt 5:1–2', '“his disciples came unto him”', 'The place and the hearers at the opening of the discourse.'],
    ['Matt 7:21', '“he that doeth the will of my Father which is in heaven”', 'A saying just before the parable.'],
    ['Matt 7:28–29', '“the people were astonished at his doctrine”', 'The close of the sayings.'],
    ['Luke 6:17', '“a great multitude of people”', 'The hearers named in Luke.'],
    ['Luke 6:20', '“yours is the kingdom of God”', 'The opening words of the sayings in Luke.'],
    ['Luke 6:46', '“why call ye me, Lord, Lord, and do not the things which I say?”', 'The question that comes before the parable in Luke.'],
    ['Luke 7:1', '“in the audience of the people”', 'The close of the sayings in Luke.'],
